// App logo: chrome MM on transparent (background cut out) - embedded as data
// because the GitHub snapshot push is text-only; swapped in on load.
window.MM_LOGO_SRC = "data:image/png;base64,";
document.querySelectorAll('img[src="assets/logo.png"]').forEach(function (el) { el.src = window.MM_LOGO_SRC; });
